import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        k = int(next(iterator))
    except StopIteration:
        return

    main_courses = set()
    for _ in range(k):
        main_courses.add(int(next(iterator)))

    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for i in range(1, n + 1):
        t = int(next(iterator))
        for _ in range(t):
            dep = int(next(iterator))
            adj[dep].append(i)
            in_degree[i] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    processed = set()

    while queue:
        u = queue.popleft()
        if u in processed:
            continue
        processed.add(u)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(processed) != n:
        print("-1")
        return

    needed = []
    for course in result:
        if course in main_courses:
            needed.append(course)
            if len(needed) == k:
                break

    if len(needed) < k:
        print("-1")
        return

    idx_map = {course: i for i, course in enumerate(result)}
    final_order = []
    for main_c in needed:
        idx = idx_map[main_c]
        for i in range(idx + 1):
            if result[i] not in final_order:
                final_order.append(result[i])
        if main_c not in final_order:
            final_order.append(main_c)

    seen = set()
    unique_order = []
    for c in final_order:
        if c not in seen:
            seen.add(c)
            unique_order.append(c)

    print(len(unique_order))
    print(" ".join(map(str, unique_order)))

if __name__ == "__main__":
    solve()
